CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT', 'PUBLISHED');
CREATE TABLE "AdminUser" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "token" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "userId" TEXT NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "subtitle" TEXT, "shortDescription" TEXT NOT NULL, "fullDescription" TEXT, "category" TEXT, "status" "ProjectStatus" NOT NULL DEFAULT 'DRAFT', "featured" BOOLEAN NOT NULL DEFAULT false, "displayOrder" INTEGER NOT NULL DEFAULT 0, "repositoryUrl" TEXT, "demoUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Technology" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Technology_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProjectTechnology" ("projectId" TEXT NOT NULL, "technologyId" TEXT NOT NULL, CONSTRAINT "ProjectTechnology_pkey" PRIMARY KEY ("projectId","technologyId"));
CREATE TABLE "ProjectImage" ("id" TEXT NOT NULL, "projectId" TEXT NOT NULL, "url" TEXT NOT NULL, "alt" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "ProjectImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Skill" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "displayOrder" INTEGER NOT NULL DEFAULT 0, "proficiency" TEXT, "technologyId" TEXT, CONSTRAINT "Skill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ContactMessage" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "message" TEXT NOT NULL, "isRead" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ContactMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MediaAsset" ("id" TEXT NOT NULL, "path" TEXT NOT NULL, "alt" TEXT, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MediaAsset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Profile" ("id" TEXT NOT NULL, "displayName" TEXT NOT NULL DEFAULT 'EHZAN', "title" TEXT NOT NULL, "biography" TEXT, "location" TEXT NOT NULL DEFAULT 'Kerala, India', "email" TEXT, "githubUrl" TEXT, "gitlabUrl" TEXT, "linkedinUrl" TEXT, "availability" TEXT, CONSTRAINT "Profile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email"); CREATE UNIQUE INDEX "Session_token_key" ON "Session"("token"); CREATE UNIQUE INDEX "Project_slug_key" ON "Project"("slug"); CREATE INDEX "Project_status_featured_displayOrder_idx" ON "Project"("status","featured","displayOrder"); CREATE UNIQUE INDEX "Technology_name_key" ON "Technology"("name"); CREATE INDEX "ContactMessage_isRead_createdAt_idx" ON "ContactMessage"("isRead","createdAt"); CREATE UNIQUE INDEX "MediaAsset_path_key" ON "MediaAsset"("path");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProjectTechnology" ADD CONSTRAINT "ProjectTechnology_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProjectTechnology" ADD CONSTRAINT "ProjectTechnology_technologyId_fkey" FOREIGN KEY ("technologyId") REFERENCES "Technology"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ProjectImage" ADD CONSTRAINT "ProjectImage_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Skill" ADD CONSTRAINT "Skill_technologyId_fkey" FOREIGN KEY ("technologyId") REFERENCES "Technology"("id") ON DELETE SET NULL ON UPDATE CASCADE;
